<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;

/**
 * Handles the display of the main governance dashboard.
 *
 * The dashboard summarises profit routing history, flash‑loan execution
 * history, event logs, overlay tier status, oracle freshness and
 * scenario execution summaries. Data is aggregated from files
 * generated by the scenario runner and stored under the `storage/app` path.
 */
class DashboardController extends Controller
{
    /**
     * Show the dashboard.
     */
    public function index()
    {
        // Attempt to read the most recent scenario report
        $report = [];
        if (Storage::exists('scenarioReport.json')) {
            $report = json_decode(Storage::get('scenarioReport.json'), true) ?? [];
        }

        // Load governance settings
        $settings = [];
        if (Storage::exists('governance.json')) {
            $settings = json_decode(Storage::get('governance.json'), true) ?? [];
        }

        return view('dashboard.index', [
            'report' => $report,
            'settings' => $settings,
        ]);
    }
}